"""Unofficial practice questions for USA-NA-AIO prep. Not official contest items."""

from __future__ import annotations


def _mc(pid, topic, diff, prompt, answer, explanation, choices, hints=None, tags=""):
    return {
        "public_id": pid,
        "topic": topic,
        "qtype": "multiple_choice",
        "difficulty": diff,
        "prompt": prompt,
        "answer": answer,
        "explanation": explanation,
        "hints": hints or ["Eliminate options that contradict definitions."],
        "choices": choices,
        "tags": tags,
    }


def _sa(pid, topic, diff, prompt, answer, explanation, hints=None, tags=""):
    return {
        "public_id": pid,
        "topic": topic,
        "qtype": "short_answer",
        "difficulty": diff,
        "prompt": prompt,
        "answer": answer,
        "explanation": explanation,
        "hints": hints or ["Write the shortest correct form."],
        "choices": [],
        "tags": tags,
    }


